-- [[Core/Primitives/Utils]]
Bundle["Core/Primitives/Utils"] = function(ctx)
    local I = ctx.Internal
    local UserInputService = I.UserInputService

    local function IsInputDown(inputType)
        if inputType == Enum.UserInputType.Touch then
            local ok, touches = pcall(UserInputService.GetTouches, UserInputService)
            return ok and #touches > 0 or false
        end
        if inputType == Enum.UserInputType.MouseButton1
            or inputType == Enum.UserInputType.MouseButton2
            or inputType == Enum.UserInputType.MouseButton3 then
            return UserInputService:IsMouseButtonPressed(inputType)
        end
        return true
    end

    local function Once(signal, fn)
        if not signal then return end
        if signal.Once then return signal:Once(fn) end
        local conn
        conn = signal:Connect(function(...)
            if conn.Connected then conn:Disconnect() end
            fn(...)
        end)
        return conn
    end

    local function SafeCall(fn, ...)
        if type(fn) ~= "function" then return end
        local ok, err = pcall(fn, ...)
        if not ok then warn("[Kailex] " .. tostring(err)) end
    end

    local function Sanitize(text)
        local s = tostring(text or "")
        s = s:gsub('[%c/\\:"<>|*?]', "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then s = "Untitled" end
        return s
    end

    local function ColorToHex(c)
        return string.format("#%02X%02X%02X",
            math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
    end

    local function HexToColor(hex)
        if type(hex) ~= "string" then return nil end
        local h = hex:gsub("#", "")
        if #h == 3 then
            h = h:sub(1,1):rep(2) .. h:sub(2,2):rep(2) .. h:sub(3,3):rep(2)
        end
        if #h ~= 6 then return nil end
        local r, g, b = tonumber(h:sub(1,2), 16), tonumber(h:sub(3,4), 16), tonumber(h:sub(5,6), 16)
        if r and g and b then return Color3.fromRGB(r, g, b) end
        return nil
    end

    local function RGBtoHSV(c)
        local r, g, b = c.R, c.G, c.B
        local max, min = math.max(r, g, b), math.min(r, g, b)
        local v, d = max, max - min
        local s = (max == 0) and 0 or d / max
        local h
        if d == 0 then h = 0
        elseif max == r then h = ((g - b) / d) % 6
        elseif max == g then h = (b - r) / d + 2
        else h = (r - g) / d + 4 end
        return h / 6, s, v
    end

    I.IsInputDown = IsInputDown
    I.Once = Once
    I.SafeCall = SafeCall
    I.Sanitize = Sanitize
    I.ColorToHex = ColorToHex
    I.HexToColor = HexToColor
    I.RGBtoHSV = RGBtoHSV
end


-- [[Core/Interaction/Input]]
Bundle["Core/Interaction/Input"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local UserInputService = I.UserInputService

    local InputHooks = {}
    I.InputHooks = InputHooks

    local function AddInputHook(alive, fn)
        local rec = { alive = alive, fn = fn }
        table.insert(InputHooks, rec)
        return rec
    end

    local function RemoveInputHook(rec)
        for i, r in ipairs(InputHooks) do
            if r == rec then table.remove(InputHooks, i) break end
        end
    end

    I.LibMaid:Give(UserInputService.InputBegan:Connect(function(input, gp)
        local n = #InputHooks
        if n == 0 then return end
        for i = 1, n do
            local h = InputHooks[i]
            if h and h.alive() then
                local ok, err = pcall(h.fn, input, gp)
                if not ok then warn("[Kailex] " .. tostring(err)) end
            end
        end
        if #InputHooks > 96 then
            local keep = table.create(8)
            for i = 1, #InputHooks do
                local h = InputHooks[i]
                if h.alive() then keep[#keep + 1] = h end
            end
            I.InputHooks = keep
            InputHooks = keep
        end
    end))

    local KeybindRegistry = {}
    I.KeybindRegistry = KeybindRegistry
    I.ActiveKeybindListener = nil
    I.HotElement = nil

    local function ParseKey(v)
        if typeof(v) == "EnumItem" then
            if v.EnumType == Enum.KeyCode then return v end
            return nil
        end
        if type(v) == "string" then
            local kind, name = v:match("^(%a+):(.+)$")
            if kind and kind:lower() ~= "key" then return nil end
            return Enum.KeyCode[name or v]
        end
        return nil
    end

    local function ToBinding(v)
        if typeof(v) == "EnumItem" then
            local name = tostring(v):match("%.(.+)$") or tostring(v)
            if v.EnumType == Enum.KeyCode then return { Kind = "Key", Code = v, Name = name } end
            if v.EnumType == Enum.UserInputType then return { Kind = "Mouse", Code = v, Name = name } end
        elseif type(v) == "string" then
            local kind, name = v:match("^(%a+):(.+)$")
            if kind then
                local k = kind:sub(1,1):upper() .. kind:sub(2):lower()
                if k == "Key" then
                    local kc = Enum.KeyCode[name]
                    if kc then return { Kind = "Key", Code = kc, Name = name } end
                elseif k == "Mouse" then
                    local it = Enum.UserInputType[name]
                    if it then return { Kind = "Mouse", Code = it, Name = name } end
                end
                return nil
            end
            local kc = Enum.KeyCode[v]
            if kc then return { Kind = "Key", Code = kc, Name = v } end
        end
        return nil
    end

    local function NotifyKeybindConflict(self, b)
        for _, rec in ipairs(KeybindRegistry) do
            local el = rec.el
            if el ~= self and not el._destroyed then
                local ob = el._getBinding and el:_getBinding()
                if ob and ob.Kind == b.Kind and ob.Code == b.Code then
                    Kailex:Notify({
                        Title = "Keybind conflict",
                        Text = "\"" .. b.Name .. "\" is also bound in \"" .. el.Title .. "\".",
                        Type = "Warning", Duration = 5,
                    })
                    return
                end
            end
        end
    end

    I.AddInputHook = AddInputHook
    I.RemoveInputHook = RemoveInputHook
    I.ParseKey = ParseKey
    I.ToBinding = ToBinding
    I.NotifyKeybindConflict = NotifyKeybindConflict
end


-- [[Core/Rendering/Tween]]
Bundle["Core/Rendering/Tween"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting
    local TweenService = I.TweenService

    local E, ED = Enum.EasingStyle, Enum.EasingDirection
    local Tweens = {
        Instant  = TweenInfo.new(0.05, E.Quad , ED.Out),
        Fast     = TweenInfo.new(0.12, E.Quint, ED.Out),
        Snappy   = TweenInfo.new(0.16, E.Quart, ED.Out),
        Normal   = TweenInfo.new(0.24, E.Quint, ED.Out),
        Smooth   = TweenInfo.new(0.35, E.Quart, ED.Out),
        Reveal   = TweenInfo.new(0.30, E.Quint, ED.Out),
        HoverIn  = TweenInfo.new(0.14, E.Quint, ED.Out),
        HoverOut = TweenInfo.new(0.20, E.Sine , ED.Out),
        Spring   = TweenInfo.new(0.34, E.Back , ED.Out),
        SpringBig= TweenInfo.new(0.45, E.Back , ED.Out),
        Collapse = TweenInfo.new(0.28, E.Back , ED.In ),
        Ripple   = TweenInfo.new(0.45, E.Quint, ED.Out),
        Pop      = TweenInfo.new(0.26, E.Back , ED.Out),
        PopSoft  = TweenInfo.new(0.20, E.Back , ED.Out),
        Vanish   = TweenInfo.new(0.15, E.Quad , ED.In ),
    }
    setmetatable(Tweens, { __index = function() return Tweens.Normal end })

    local ActiveTweens = setmetatable({}, { __mode = "k" })

    local function ScaledInfo(info)
        local m = tonumber(Setting.MotionScale) or 1
        if m == 1 then return info end
        local t = info.Time * m
        if t < 0.02 then t = 0.02 end
        return TweenInfo.new(t, info.EasingStyle, info.EasingDirection, info.RepeatCount, info.Reverses, info.DelayTime)
    end

    local function Tween(inst, preset, props, done)
        if not inst or not inst.Parent then return nil end
        if type(props) ~= "table" then return nil end
        local info = Tweens[preset]
        if typeof(preset) == "TweenInfo" then info = preset end
        info = ScaledInfo(info)

        local book = ActiveTweens[inst]
        if not book then book = {} ActiveTweens[inst] = book end
        for prop in pairs(props) do
            local prev = book[prop]
            if prev then pcall(prev.Cancel, prev) book[prop] = nil end
        end

        local ok, tween = pcall(TweenService.Create, TweenService, inst, info, props)
        if not ok then
            warn("[Kailex] tween failed: " .. tostring(inst))
            return nil
        end
        for prop in pairs(props) do book[prop] = tween end

        if done then
            I.Once(tween.Completed, function(state)
                if state == Enum.PlaybackState.Completed then I.SafeCall(done) end
            end)
        end
        I.Once(tween.Completed, function()
            local b = ActiveTweens[inst]
            if b then
                for prop in pairs(props) do
                    if b[prop] == tween then b[prop] = nil end
                end
            end
        end)

        tween:Play()
        return tween
    end

    I.Tween = Tween
    I.Tweens = Tweens
end


