        },
        Sakura = {
            Background = RGB(18,14,18),   Surface = RGB(25,19,24),    SurfaceLight = RGB(33,25,31),
            Element = RGB(36,27,34),      ElementHover = RGB(46,35,43),
            Stroke = RGB(54,41,50),       StrokeBright = RGB(80,61,74),
            Text = RGB(244,236,242),      SubText = RGB(168,150,162),
            Accent = RGB(240,146,196),    AccentHover = RGB(246,169,211), OnAccent = RGB(26,12,20),
            Success = RGB(158,206,106),   Warning = RGB(224,175,104), Error = RGB(247,118,142),
            TabBar = RGB(21,16,20),
        },
        Daylight = {
            Background = RGB(244,246,250), Surface = RGB(255,255,255), SurfaceLight = RGB(236,240,247),
            Element = RGB(239,243,249),    ElementHover = RGB(226,233,244),
            Stroke = RGB(210,218,232),     StrokeBright = RGB(178,190,212),
            Text = RGB(28,34,48),          SubText = RGB(106,116,138),
            Accent = RGB(66,113,244),      AccentHover = RGB(90,132,247), OnAccent = RGB(255,255,255),
            Success = RGB(72,163,87),      Warning = RGB(196,142,30),  Error = RGB(219,68,94),
            TabBar = RGB(240,242,247),
        },
    }

    local ThemeKeys = {
        "Background","Surface","SurfaceLight","Element","ElementHover","Stroke","StrokeBright",
        "Text","SubText","Accent","AccentHover","OnAccent","Success","Warning","Error","TabBar",
    }

    I.CurrentTheme = Themes.Nocturne
    local ThemeBindings = setmetatable({}, { __mode = "k" })

    local function Bind(inst, prop, key)
        if not inst then return inst end
        local b = ThemeBindings[inst]
        if not b then b = {} ThemeBindings[inst] = b end
        b[prop] = key
        local v = I.CurrentTheme[key]
        if v ~= nil then inst[prop] = v end
        return inst
    end

    local PendingTheme, ThemeQueued = nil, false
    local function ApplyTheme(theme)
        if type(theme) == "string" then theme = Themes[theme] or I.CurrentTheme end
        PendingTheme = theme
        if ThemeQueued then return end
        ThemeQueued = true
        task.defer(function()
            ThemeQueued = false
            local t = PendingTheme
            if t then
                I.CurrentTheme = t
                for inst, binds in pairs(ThemeBindings) do
                    for prop, key in pairs(binds) do
                        local v = t[key]
                        if v ~= nil then inst[prop] = v end
                    end
                end
                Kailex.ThemeChanged:Fire(t)
            end
        end)
    end

    function Kailex:GetThemes()
        local t = {}
        for k in pairs(Themes) do table.insert(t, k) end
        table.sort(t)
        return t
    end

    function Kailex:SetTheme(theme)
        ApplyTheme(theme)
    end

    I.Themes = Themes
    I.ThemeKeys = ThemeKeys
    I.Bind = Bind
    I.ApplyTheme = ApplyTheme
end


-- [[Core/Rendering/Instance]]
Bundle["Core/Rendering/Instance"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting

    local TextRegistry = setmetatable({}, { __mode = "k" })
    local TextBaseSize = setmetatable({}, { __mode = "k" })

    local function TS(n)
        return math.floor(n * (tonumber(Setting.TextScale) or 1) + 0.5)
    end

    local TextScaleQueued = false
    local function ApplyTextScale()
        if TextScaleQueued then return end
        TextScaleQueued = true
        task.defer(function()
            TextScaleQueued = false
            for inst in pairs(TextRegistry) do
                local base = TextBaseSize[inst]
                if base then
                    pcall(function() inst.TextSize = TS(base) end)
                end
            end
        end)
    end

    local function SetProps(inst, props)
        for prop, value in pairs(props) do
            inst[prop] = value
        end
    end

    local function Create(className, props)
        props = props or {}
        local inst = Instance.new(className)
        local parent = props.Parent
        local children = props.Children
        if parent then props.Parent = nil end
        if children then props.Children = nil end
        if (className == "TextLabel" or className == "TextButton" or className == "TextBox")
            and type(props.TextSize) == "number" then
            TextBaseSize[inst] = props.TextSize
            TextRegistry[inst] = true
            props.TextSize = TS(props.TextSize)
        end
        local ok, err = pcall(SetProps, inst, props)
        if not ok then
            warn("[Kailex] property error (" .. className .. "): " .. tostring(err))
            for prop, value in pairs(props) do
                pcall(function() inst[prop] = value end)
            end
        end
        if children then
            for _, child in ipairs(children) do child.Parent = inst end
        end
        if parent then inst.Parent = parent end
        return inst
    end

    local function Corner(radius)
        return Create("UICorner", { CornerRadius = UDim.new(0, radius or 8) })
    end

    local function StrokeBind(thickness, key, transparency)
        local s = Create("UIStroke", {
            Thickness = thickness or 1,
            Transparency = transparency or 0.6,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        })
        I.Bind(s, "Color", key or "Stroke")
        return s
    end

    local function Icon(parent, kind, colorKey)
        colorKey = colorKey or "SubText"
        local holder = Create("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(14, 14),
            Parent = parent,
        })
        local function bar(w, h, x, y, rot)
            local f = Create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(w, h),
                Position = UDim2.fromScale(x, y),
                Rotation = rot or 0,
                BackgroundColor3 = I.CurrentTheme[colorKey],
                BorderSizePixel = 0,
                Parent = holder,
            })
            I.Bind(f, "BackgroundColor3", colorKey)
        end
        if kind == "Minimize" then
            bar(10, 2, 0.5, 0.5)
        elseif kind == "Close" then
            bar(11, 2, 0.5, 0.5, 45)
            bar(11, 2, 0.5, 0.5, -45)
        elseif kind == "Chevron" then
            bar(7, 2, 0.32, 0.55, 45)
            bar(7, 2, 0.68, 0.55, -45)
        elseif kind == "Search" then
            local ring = Create("Frame", {
                Size = UDim2.fromOffset(8, 8),
                Position = UDim2.fromOffset(1, 1),
                BackgroundTransparency = 1,
                Parent = holder,
                Children = { Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
            })
            I.Bind(Create("UIStroke", { Thickness = 1.6, Parent = ring }), "Color", colorKey)
            bar(6, 2, 0.72, 0.72, 45)
        elseif kind == "Grip" then
            bar(2, 5, 0.30, 0.72, 45)
            bar(2, 7, 0.52, 0.52, 45)
            bar(2, 9, 0.74, 0.32, 45)
        elseif kind == "Gear" then
            local ring = Create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(6, 6),
                BackgroundTransparency = 1,
                Parent = holder,
                Children = { Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
            })
            I.Bind(Create("UIStroke", { Thickness = 1.6, Parent = ring }), "Color", colorKey)
            for i = 0, 7 do
                local ang = i * 45
                local f = Create("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, math.cos(math.rad(ang)) * 5, 0.5, math.sin(math.rad(ang)) * 5),
                    Size = UDim2.fromOffset(3, 2),
                    Rotation = ang,
                    BackgroundColor3 = I.CurrentTheme[colorKey],
                    BorderSizePixel = 0,
                    Parent = holder,
                })
                I.Bind(f, "BackgroundColor3", colorKey)
            end
        elseif kind == "Check" then
            bar(6, 2, 0.34, 0.60, 45)
            bar(9, 2, 0.64, 0.42, -45)
        elseif kind == "Reset" then
            local ring = Create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(9, 9),
                BackgroundTransparency = 1,
                Parent = holder,
                Children = { Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
            })
            I.Bind(Create("UIStroke", { Thickness = 1.6, Parent = ring }), "Color", colorKey)
            bar(4, 2, 0.82, 0.16, 0)
            bar(3, 2, 0.68, 0.22, 90)
        elseif kind == "ResizeH" then
            bar(6, 2, 0.24, 0.40, -45)
            bar(6, 2, 0.24, 0.60, 45)
            bar(11, 2, 0.5, 0.5, 0)
            bar(6, 2, 0.76, 0.40, 45)
            bar(6, 2, 0.76, 0.60, -45)
        elseif kind == "Pin" then
            local ring = Create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.34),
                Size = UDim2.fromOffset(7, 7),
                BackgroundColor3 = I.CurrentTheme[colorKey],
                BorderSizePixel = 0,
                Parent = holder,
                Children = { Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
            })
            I.Bind(ring, "BackgroundColor3", colorKey)
            bar(2, 6, 0.5, 0.76)
        end
        return holder
    end

    local function AddHover(obj, opts)
        if I.Device.IsTouch then return end
        opts = opts or {}
        local baseT = opts.BaseTransparency
        if baseT == nil then baseT = obj.BackgroundTransparency end
        local hoverT = opts.HoverTransparency
        if hoverT == nil then hoverT = baseT end
        local hoverKey = opts.HoverKey or "ElementHover"
        local baseKey  = opts.BaseKey or "Element"
        obj.MouseEnter:Connect(function()
            if obj:GetAttribute("NoHoverFX") or obj:GetAttribute("Disabled") then return end
            I.PlaySound("Hover", 0.12)
            I.Tween(obj, "HoverIn", { BackgroundColor3 = I.CurrentTheme[hoverKey], BackgroundTransparency = hoverT })
            local stroke = obj:FindFirstChildOfClass("UIStroke")
            if stroke and not opts.IgnoreStroke then
                I.Tween(stroke, "HoverIn", { Color = I.CurrentTheme.StrokeBright, Transparency = 0.25 })
            end
        end)

        obj.MouseLeave:Connect(function()
            I.Tween(obj, "HoverOut", { BackgroundColor3 = I.CurrentTheme[baseKey], BackgroundTransparency = baseT })
            local stroke = obj:FindFirstChildOfClass("UIStroke")
            if stroke and not opts.IgnoreStroke then
                I.Tween(stroke, "HoverOut", { Color = I.CurrentTheme.Stroke, Transparency = opts.StrokeTransparency or 0.6 })
            end
        end)
    end

    I.TS = TS
    I.ApplyTextScale = ApplyTextScale
    I.Create = Create
    I.Corner = Corner
    I.StrokeBind = StrokeBind
    I.Icon = Icon
    I.AddHover = AddHover
end


-- [[Core/Services/Save]]
Bundle["Core/Services/Save"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local HttpService = I.HttpService
    local Setting = I.Setting
    local fs = I.fs
    local HasFileSystem = I.HasFileSystem

    local SaveManager = {
        Folder = Setting.SaveFolder,
        File   = tostring(game.PlaceId) .. ".json",
        Data   = {},
        Delay  = 1,
    }
    SaveManager.DataChanged = I.Signal.new()

    do
        if HasFileSystem then
            pcall(fs.makefolder, SaveManager.Folder)
            local path = SaveManager.Folder .. "/" .. SaveManager.File
            if fs.isfile(path) then
                local ok, res = pcall(function()
                    return HttpService:JSONDecode(fs.readfile(path))
                end)
                if ok and type(res) == "table" then
                    SaveManager.Data = res
                else
                    local ok2, res2 = pcall(function()
                        return HttpService:JSONDecode(fs.readfile(path .. ".bak"))
                    end)
                    if ok2 and type(res2) == "table" then SaveManager.Data = res2 end
                end
            end
        end
    end

    local function IsInternalKey(key)
        return type(key) == "string" and key:sub(1, 2) == "__"
    end

    function SaveManager:Set(key, value)
        if self.Data[key] == value then return end
        self.Data[key] = value
        if not Setting.AutoSave then return end
        if self._pending then return end
        self._pending = true
        task.delay(self.Delay, function()
            self._pending = false
            self:Flush()
        end)
    end

    function SaveManager:Flush()
        if not HasFileSystem then return end
        local ok, err = pcall(function()
            local path = self.Folder .. "/" .. self.File
            if fs.isfile(path) then
                pcall(function() fs.writefile(path .. ".bak", fs.readfile(path)) end)
            end
            fs.writefile(path, HttpService:JSONEncode(self.Data))
        end)
        if not ok then warn("[Kailex] save failed: " .. tostring(err)) end
    end

    function SaveManager:Get(key, default)
        local v = self.Data[key]
        if v == nil then return default end
        if default ~= nil and typeof(v) ~= typeof(default) then return default end
        return v
    end

    function SaveManager:Clear()
        self.Data = {}
        self:Flush()
        self.DataChanged:Fire()
    end

    local function SaveValue(key, value)
        if key then SaveManager:Set(key, value) end
    end

    local Configs = { Folder = SaveManager.Folder .. "/Profiles" }

    function Configs:Path(name)
        return self.Folder .. "/" .. I.Sanitize(name) .. ".json"
    end

    function Configs:List()
        if not HasFileSystem then return {} end
        local names = {}
        local ok, files = pcall(fs.listfiles, self.Folder)
        if ok and type(files) == "table" then
            for _, f in ipairs(files) do
                local name = tostring(f):match("([^/\\]+)%.json$")
                if name then table.insert(names, name) end
            end
        end
        table.sort(names)
        return names
    end

    function Configs:Save(name)
        if not HasFileSystem or not name or name == "" then return false end
        pcall(fs.makefolder, self.Folder)
        return pcall(function()
            local export = {}
            for k, v in pairs(SaveManager.Data) do
                if not IsInternalKey(k) then export[k] = v end
            end
            fs.writefile(self:Path(name), HttpService:JSONEncode(export))
        end)
    end

    function Configs:Load(name)
        if not HasFileSystem or not name then return false end
        local ok, res = pcall(function()
            return HttpService:JSONDecode(fs.readfile(self:Path(name)))
        end)
        if ok and type(res) == "table" then
            local merged = {}
            for k, v in pairs(res) do merged[k] = v end
            for k, v in pairs(SaveManager.Data) do
                if IsInternalKey(k) then merged[k] = v end
            end
            SaveManager.Data = merged
            SaveManager:Flush()
            SaveManager.DataChanged:Fire()
            return true
        end
        return false
    end

    function Configs:Delete(name)
        if not HasFileSystem or not name then return false end
        return pcall(fs.delfile, self:Path(name))
    end

    local SaveReloadRegistry = {}
    I.LibMaid:Give(SaveManager.DataChanged:Connect(function()
        for key, fns in pairs(SaveReloadRegistry) do
            local n = #fns
            if n > 0 then
                local v = SaveManager:Get(key, nil)
                if v ~= nil then
                    for i = 1, n do I.SafeCall(fns[i], v) end
                end
            end
        end
    end))

    I.SaveManager = SaveManager
    I.Configs = Configs
    I.SaveValue = SaveValue
    I.IsInternalKey = IsInternalKey
end


-- [[Core/Services/Sound]]
Bundle["Core/Services/Sound"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local Setting = I.Setting
    local SoundService = I.SoundService

    local Audio = {
        Hover    = { Id = "rbxasset://sounds/electronicpingshort.wav", Speed = 1.85, Vol = 0.05 },
        Click    = { Id = "rbxasset://sounds/snap.mp3",                Speed = 1.25, Vol = 0.45 },
        ToggleOn = { Id = "rbxasset://sounds/electronicpingshort.wav", Speed = 1.15, Vol = 0.35 },
        ToggleOff= { Id = "rbxasset://sounds/electronicpingshort.wav", Speed = 0.82, Vol = 0.32 },
        Slider   = { Id = "rbxasset://sounds/snap.mp3",                Speed = 1.55, Vol = 0.25 },
        Error    = { Id = "rbxasset://sounds/snap.mp3",                Speed = 0.55, Vol = 0.55 },
        Master   = 1,
    }
    Kailex.Audio = Audio

    local SoundPool = {}
    local SoundInstances = {}

    local function PlaySound(kind, scale)
        if not Setting.Sounds then return end
        local a = Audio[kind]
        if type(a) ~= "table" or a.Id == "" then return end
        pcall(function()
            local pool = SoundPool[a.Id]
            if not pool then pool = {} SoundPool[a.Id] = pool end
            local s
            for i = 1, #pool do
                local c = pool[i]
                if not c.IsPlaying then s = table.remove(pool, i) break end
            end
            if not s then
                s = Instance.new("Sound")
                s.Parent = SoundService
                table.insert(SoundInstances, s)
                s.Ended:Connect(function()
                    task.defer(function()
                        if s.Parent ~= SoundService then return end
                        if #pool < 8 then
                            if not table.find(pool, s) then table.insert(pool, s) end
                        else
                            s:Destroy()
                            local idx = table.find(SoundInstances, s)
                            if idx then table.remove(SoundInstances, idx) end
                        end
                    end)
                end)
            end
            s.SoundId = a.Id
            s.PlaybackSpeed = a.Speed or 1
            s.Volume = math.clamp((a.Vol or 0.4) * (scale or 1) * (Audio.Master or 1), 0, 1)
            s.TimePosition = 0
            s:Play()
        end)
    end

    I.Audio = Audio
    I.PlaySound = PlaySound
    I.SoundInstances = SoundInstances
    I.SoundPool = SoundPool
end


-- [[Core/Misc/Gui]]
Bundle["Core/Misc/Gui"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local Setting = I.Setting
    local Workspace = I.Workspace

    local ScreenGui = I.Create("ScreenGui", {
        Name = "KailexUI",
        IgnoreGuiInset = true,
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        DisplayOrder = 100,
    })
    Kailex.CurrentScreenGui = ScreenGui
    pcall(I.protect_gui, ScreenGui)
    ScreenGui.Parent = I.SafeParent

    local LayerWindows = I.Create("Frame", { Name = "Windows", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = ScreenGui })
    local LayerOverlay = I.Create("Frame", { Name = "Overlay",  BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = ScreenGui })
    local LayerNotify  = I.Create("Frame", { Name = "Notify",   BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = ScreenGui })
    local LayerTooltip = I.Create("Frame", { Name = "Tooltip",  BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Parent = ScreenGui })

    local RootScale = I.Create("UIScale", { Parent = ScreenGui })
    local Camera = Workspace.CurrentCamera
    I.Viewport = Vector2.new(1920, 1080)

    local ViewportHooks = {}
    I.ViewportHooks = ViewportHooks

    local function GetScale()
        return RootScale and RootScale.Scale or 1
    end

    local function ClampFloat(inst)
        local s = GetScale()
        local w, h = inst.AbsoluteSize.X, inst.AbsoluteSize.Y
        if w < 1 or h < 1 then return end
        local x, y = inst.AbsolutePosition.X, inst.AbsolutePosition.Y
        local nx = math.clamp(x, 8, math.max(8, I.Viewport.X - w - 8))
        local ny = math.clamp(y, 8, math.max(8, I.Viewport.Y - h - 8))
        if nx ~= x or ny ~= y then
            inst.Position = UDim2.fromOffset(nx / s, ny / s)
        end
    end
    I.ClampFloat = ClampFloat

    local function UpdateViewport()
        if not Camera then return end
        I.Viewport = Camera.ViewportSize
        local short = math.min(I.Viewport.X, I.Viewport.Y)
        local s = math.clamp(short / 880, 0.85, 1.1)
        if I.Device.IsTouch then s = math.max(s, 1) end
        RootScale.Scale = s * (tonumber(Setting.UIScale) or 1)
        for _, win in ipairs(Kailex.Windows) do
            if not win._destroyed then pcall(function() win:OnViewport() end) end
        end
        for _, fn in ipairs(ViewportHooks) do pcall(fn) end
    end

    local CameraConn = nil
    local function BindCamera(cam)
        if cam == Camera then return end
        if CameraConn then CameraConn:Disconnect() CameraConn = nil end
        Camera = cam
        if cam then
            CameraConn = cam:GetPropertyChangedSignal("ViewportSize"):Connect(UpdateViewport)
        end
    end
    BindCamera(Workspace.CurrentCamera)
    I.LibMaid:Give(Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        BindCamera(Workspace.CurrentCamera)
    end))
    I.LibMaid:Give(function()
        if CameraConn then CameraConn:Disconnect() end
    end)

    I.ScreenGui = ScreenGui
    I.LayerWindows = LayerWindows
    I.LayerOverlay = LayerOverlay
    I.LayerNotify = LayerNotify
    I.LayerTooltip = LayerTooltip
    I.GetScale = GetScale
    I.UpdateViewport = UpdateViewport
end


-- [[Core/Interaction/Modal]]
Bundle["Core/Interaction/Modal"] = function(ctx)
    local I = ctx.Internal

    local ModalManager = { Stack = {} }
    I.ModalManager = ModalManager

    function ModalManager.Push(owner, closer)
        local entry = { Owner = owner, Close = closer }
        table.insert(ModalManager.Stack, entry)
        return entry
    end

    function ModalManager.Remove(entry)
        if not entry then return end
        for i = #ModalManager.Stack, 1, -1 do
            if ModalManager.Stack[i] == entry then
                table.remove(ModalManager.Stack, i)
                return
            end
        end
    end

    function ModalManager.CloseAll(owner)
        for i = #ModalManager.Stack, 1, -1 do
            local e = ModalManager.Stack[i]
            if owner == nil or e.Owner == nil or e.Owner == owner then
                table.remove(ModalManager.Stack, i)
                pcall(e.Close)
            end
        end
    end
end


-- [[Core/Interaction/Drag]]
Bundle["Core/Interaction/Drag"] = function(ctx)
    local I = ctx.Internal
    local UserInputService = I.UserInputService
    local RunService = I.RunService

    local DragManager = { Active = nil }
    I.DragManager = DragManager

    local function ClampWindowToScreen(root)
        local s = I.GetScale()
        local margin = 8
        local w, h = root.AbsoluteSize.X, root.AbsoluteSize.Y
        local x, y = root.AbsolutePosition.X, root.AbsolutePosition.Y
        local nx = math.clamp(x, margin, math.max(margin, I.Viewport.X - w - margin))
        local ny = math.clamp(y, margin, math.max(margin, I.Viewport.Y - h - margin))
        if nx ~= x or ny ~= y then
            local ap = root.AnchorPoint
            root.Position = UDim2.fromOffset(
                (nx + ap.X * w) / s,
                (ny + ap.Y * h) / s
            )
        end
    end
    I.ClampWindowToScreen = ClampWindowToScreen

    local function MakeDraggable(handle, target, opts)
        opts = opts or {}
        local threshold = opts.Threshold or 6
        local dragging = false
        local maid = I.Maid.new()

        maid:Give(handle.InputBegan:Connect(function(input)
            if dragging or DragManager.Active ~= nil then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end

            dragging = true
            DragManager.Active = target

            if target.AnchorPoint.X ~= 0 or target.AnchorPoint.Y ~= 0 then
                local s = I.GetScale()
                target.AnchorPoint = Vector2.new(0, 0)
                target.Position = UDim2.fromOffset(target.AbsolutePosition.X / s, target.AbsolutePosition.Y / s)
            end

            if opts.OnStart then I.SafeCall(opts.OnStart, target) end

            local startPos = target.Position
            local startMouse = UserInputService:GetMouseLocation()
            local moved = false
            local dragMaid = I.Maid.new()
            maid:Give(dragMaid)

            local function finish()
                if not dragging then return end
                dragging = false
                if DragManager.Active == target then DragManager.Active = nil end
                handle:SetAttribute("Dragging", nil)
                dragMaid:Destroy()
                if moved and opts.OnEnd then I.SafeCall(opts.OnEnd) end
            end

            dragMaid:Give(UserInputService.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1
                    or inp.UserInputType == Enum.UserInputType.Touch then
                    finish()
                end
            end))
            dragMaid:Give(handle.Destroying:Connect(finish))
            dragMaid:Give(RunService.Heartbeat:Connect(function()
                if not I.IsInputDown(input.UserInputType) then finish() end
            end))
            dragMaid:Give(RunService.RenderStepped:Connect(function()
                if not dragging then return end
                local mouse = UserInputService:GetMouseLocation()
                local dx, dy = mouse.X - startMouse.X, mouse.Y - startMouse.Y
                if not moved and math.abs(dx) + math.abs(dy) > threshold then
                    moved = true
                    handle:SetAttribute("Dragging", true)
                end
                if moved then
                    local s = I.GetScale()
                    target.Position = UDim2.fromOffset(startPos.X.Offset + dx / s, startPos.Y.Offset + dy / s)
                    if opts.Clamp then ClampWindowToScreen(target) end
                end
            end))
        end))

        I.Once(handle.Destroying, function() maid:Destroy() end)
        return maid
    end
    I.MakeDraggable = MakeDraggable

    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            task.defer(function()
                local anyDown = false
                local ok, btns = pcall(UserInputService.GetMouseButtonsPressed, UserInputService)
                if ok and type(btns) == "table" then
                    anyDown = #btns > 0
                end
                if not anyDown then DragManager.Active = nil end
            end)
        end
    end)
end


-- [[Core/Interaction/Ripple]]
Bundle["Core/Interaction/Ripple"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting
    local UserInputService = I.UserInputService

    local RipplePool = {}
    I.RipplePool = RipplePool

    local function ApplyRipple(target, inputPos)
        if not Setting.Effects then return end
        if not target or not target.Parent or I.Device.IsConsole then return end
        local count = target:GetAttribute("__rpl")
        if not count then
            target:SetAttribute("__rplPrev", target.ClipsDescendants)
        end
        target.ClipsDescendants = true
        count = (count or 0) + 1
        target:SetAttribute("__rpl", count)

        local mouse = inputPos or UserInputService:GetMouseLocation()
        local s = I.GetScale()
        local relX = (mouse.X - target.AbsolutePosition.X) / s
        local relY = (mouse.Y - target.AbsolutePosition.Y) / s

        local function newRipple()
            local r = I.Create("Frame", {
                BackgroundColor3 = Color3.new(1, 1, 1),
                BorderSizePixel = 0,
                Visible = false,
                AnchorPoint = Vector2.new(0.5, 0.5),
                ZIndex = 50,
                Children = { I.Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
            })
            I.Once(r.Destroying, function()
                for i, x in ipairs(RipplePool) do
                    if x == r then table.remove(RipplePool, i) break end
                end
            end)
            table.insert(RipplePool, r)
            return r
        end

        local rpl
        for _, r in ipairs(RipplePool) do
            if not r.Visible and not r.Parent then rpl = r break end
        end
        if not rpl then rpl = newRipple() end

        if not pcall(function() rpl.Parent = target end) then
            for i, r in ipairs(RipplePool) do
                if r == rpl then table.remove(RipplePool, i) break end
            end
            rpl = newRipple()
            rpl.Parent = target
        end

        rpl.Position = UDim2.fromOffset(relX, relY)
        rpl.Size = UDim2.fromOffset(0, 0)
        rpl.BackgroundTransparency = 0.68
        rpl.Visible = true

        local size = math.max(target.AbsoluteSize.X, target.AbsoluteSize.Y) * 1.2
        local t = I.Tween(rpl, "Ripple", {
            Size = UDim2.fromOffset(size / s, size / s),
            BackgroundTransparency = 1,
        })
        I.Once(t.Completed, function()
            if rpl.Visible then
                rpl.Visible = false
                rpl.Parent = nil
            end
            local c = (target:GetAttribute("__rpl") or 1) - 1
            if c > 0 then
                target:SetAttribute("__rpl", c)
            else
                target:SetAttribute("__rpl", nil)
                target.ClipsDescendants = target:GetAttribute("__rplPrev") == true
                target:SetAttribute("__rplPrev", nil)
            end
        end)
    end

    I.ApplyRipple = ApplyRipple
end


-- [[Core/Rendering/FX]]
Bundle["Core/Rendering/FX"] = function(ctx)
    local I = ctx.Internal

    local FX = {}

    function FX.Shake(inst, dist)
        if not inst then return end
        local orig = inst.Position
        local d = dist or 8
        I.Tween(inst, "Fast", { Position = orig + UDim2.fromOffset(d, 0) }, function()
            I.Tween(inst, "Fast", { Position = orig + UDim2.fromOffset(-d * 0.7, 0) }, function()
                I.Tween(inst, "Fast", { Position = orig + UDim2.fromOffset(d * 0.35, 0) }, function()
                    I.Tween(inst, "Snappy", { Position = orig })
                end)
            end)
        end)
    end

    I.FX = FX
end


-- [[Core/Overlays/Tooltip]]
Bundle["Core/Overlays/Tooltip"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting
    local UserInputService = I.UserInputService

    local Tooltip = {}
    I.Tooltip = Tooltip

    do
        local frame = I.Create("Frame", {
            BackgroundColor3 = I.CurrentTheme.SurfaceLight,
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(0, 26),
            Visible = false,
            ZIndex = 100,
            Parent = I.LayerTooltip,
            Children = { I.Corner(6), I.StrokeBind(1, "Stroke", 0.35) },
        })
        I.Bind(frame, "BackgroundColor3", "SurfaceLight")
        local label = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, -16, 1, 0),
            Position = UDim2.fromOffset(8, 0),
            Font = Enum.Font.Gotham,
            TextSize = 12,
            TextColor3 = I.CurrentTheme.Text,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = frame,
        })
        I.Bind(label, "TextColor3", "Text")
        local tipScale = I.Create("UIScale", { Scale = 1, Parent = frame })
        local maid = I.Maid.new()
        local hideToken = 0
        local tipW, tipH = 0, 26

        local function position()
            local m = UserInputService:GetMouseLocation()
            local s = I.GetScale()
            local x, y = m.X + 14, m.Y + 18
            if x + tipW > I.Viewport.X - 8 then x = m.X - tipW - 14 end
            if y + tipH > I.Viewport.Y - 8 then y = m.Y - tipH - 16 end
            if x < 8 then x = 8 end
            if y < 8 then y = 8 end
            frame.Position = UDim2.fromOffset(x / s, y / s)
        end

        function Tooltip.Show(text)
            if not text or text == "" then return end
            hideToken += 1
            label.Text = text
            local bounds = I.TextService:GetTextSize(text, I.TS(12), Enum.Font.Gotham, Vector2.new(340, 1000))
            tipW = math.min(bounds.X + 18, 358)
            tipH = math.clamp(bounds.Y + 10, 24, 92)
            frame.Size = UDim2.fromOffset(tipW, tipH)
            frame.Visible = true
            frame.BackgroundTransparency = 1
            label.TextTransparency = 1
            tipScale.Scale = 0.93
            position()
            maid:Clean()
            maid:Give(UserInputService.InputChanged:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseMovement then position() end
            end))
            I.Tween(frame, "Fast", { BackgroundTransparency = 0.06 })
            I.Tween(label, "Fast", { TextTransparency = 0 })
            I.Tween(tipScale, "PopSoft", { Scale = 1 })
        end

        function Tooltip.Hide()
            if not frame.Visible then return end
            hideToken += 1
            local tk = hideToken
            I.Tween(tipScale, "Vanish", { Scale = 0.95 })
            I.Tween(frame, "Vanish", { BackgroundTransparency = 1 })
            I.Tween(label, "Vanish", { TextTransparency = 1 })
            task.delay(0.16, function()
                if hideToken == tk then frame.Visible = false end
            end)
            maid:Clean()
        end
    end

    local function AddTooltip(obj, ref)
        local function getText()
            return type(ref) == "table" and ref.Text or ref
        end
        if I.Device.IsTouch then
            obj.InputBegan:Connect(function(input)
                if input.UserInputType ~= Enum.UserInputType.Touch then return end
                local text = getText()
                if not text or text == "" then return end
                local token = {}
                Tooltip._touchToken = token
                task.delay(0.55, function()
                    if Tooltip._touchToken == token then Tooltip.Show(getText()) end
                end)
            end)
            obj.InputEnded:Connect(function()
                Tooltip._touchToken = nil
                Tooltip.Hide()
            end)
        else
            obj.MouseEnter:Connect(function()
                local text = getText()
                if not text or text == "" then return end
                Tooltip.Show(text)
            end)
            obj.MouseLeave:Connect(Tooltip.Hide)
        end
        obj.Destroying:Connect(Tooltip.Hide)
    end
    I.AddTooltip = AddTooltip
end


-- [[Core/Overlays/Notify]]
Bundle["Core/Overlays/Notify"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local Setting = I.Setting

    local NotificationLog = {}
    Kailex.GetNotificationLog = function()
        local out = table.create(#NotificationLog)
        for i, e in ipairs(NotificationLog) do out[i] = table.clone(e) end
        return out
    end

    local MAX_ACTIVE = I.Device.IsTouch and 3 or 5
    local POOL_CAP = MAX_ACTIVE + 3
    local TypeColors = { Info = "Accent", Success = "Success", Warning = "Warning", Error = "Error" }
    local queue = {}
    local active = 0
    local pool = {}

    local container = I.Create("Frame", {
        BackgroundTransparency = 1,
        AnchorPoint = Vector2.new(Setting.RTL and 0 or 1, 1),
        Position = Setting.RTL and UDim2.new(0, 14, 1, -14) or UDim2.new(1, -14, 1, -14),
        Size = UDim2.new(0, 320, 1, -28),
        Parent = I.LayerNotify,
        Children = {
            I.Create("UIListLayout", {
                SortOrder = Enum.SortOrder.LayoutOrder,
                VerticalAlignment = Enum.VerticalAlignment.Bottom,
                HorizontalAlignment = Setting.RTL and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right,
                Padding = UDim.new(0, 8),
            }),
        },
    })

    local process

    local function newCard()
        local card = I.Create("Frame", {
            BackgroundColor3 = I.CurrentTheme.Surface,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 0),
            Visible = false,
            Parent = container,
            Children = { I.Create("UICorner", { CornerRadius = UDim.new(0, 10) }) },
        })
        I.Bind(card, "BackgroundColor3", "Surface")
        local stroke = I.StrokeBind(1, "Stroke", 0.5)
        stroke.Parent = card
        local dot = I.Create("Frame", {
            Size = UDim2.fromOffset(7, 7),
            Position = UDim2.fromOffset(12, 11),
            BackgroundColor3 = I.CurrentTheme.Accent,
            BorderSizePixel = 0,
            ZIndex = 2,
            Parent = card,
            Children = { I.Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
        })
        local title = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(26, 8),
            Size = UDim2.new(1, -38, 0, 16),
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextColor3 = I.CurrentTheme.Text,
            TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 2,
            Parent = card,
        })
        I.Bind(title, "TextColor3", "Text")
        local body = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(12, 26),
            Size = UDim2.new(1, -24, 0, 0),
            Font = Enum.Font.Gotham,
            TextSize = 12,
            TextColor3 = I.CurrentTheme.SubText,
            TextWrapped = true,
            TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            ZIndex = 2,
            Parent = card,
        })
        I.Bind(body, "TextColor3", "SubText")
        local actions = I.Create("Frame", {
            BackgroundTransparency = 1,
            Position = UDim2.new(0, 12, 1, -32),
            Size = UDim2.new(1, -24, 0, 26),
            ZIndex = 2,
            Parent = card,
            Children = {
                I.Create("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalAlignment = Setting.RTL and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right,
                    Padding = UDim.new(0, 6),
                    SortOrder = Enum.SortOrder.LayoutOrder,
                }),
            },
        })
        local progress = I.Create("Frame", {
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new(0, 12, 1, -5),
            Size = UDim2.new(1, -24, 0, 2),
            BackgroundColor3 = I.CurrentTheme.Accent,
            BorderSizePixel = 0,
            ZIndex = 1,
            Parent = card,
            Children = { I.Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
        })
        local hit = I.Create("TextButton", {
            BackgroundTransparency = 1,
            Text = "",
            Size = UDim2.fromScale(1, 1),
            ZIndex = 3,
            Parent = card,
        })
        local cardScale = I.Create("UIScale", { Scale = 1, Parent = card })
        local dotScale = I.Create("UIScale", { Scale = 1, Parent = dot })
        local meta = {
            Card = card, Stroke = stroke, Dot = dot, Title = title,
            Body = body, Actions = actions, Progress = progress, Hit = hit, InUse = false,
            CardScale = cardScale, DotScale = dotScale,
        }
        table.insert(pool, meta)
        return meta
    end

    local function getFreeCard()
        for _, m in ipairs(pool) do
            if not m.InUse and not m.Card.Visible then return m end
        end
        if #pool < POOL_CAP then return newCard() end
        return nil
    end

    local function dismiss(meta)
        if not meta.InUse then return end
        meta.InUse = false
        active = math.max(0, active - 1)
        if meta.DelayThread then pcall(task.cancel, meta.DelayThread) meta.DelayThread = nil end
        if meta.ProgressTween then pcall(function() meta.ProgressTween:Cancel() end) meta.ProgressTween = nil end
        if meta.Maid then meta.Maid:Destroy() meta.Maid = nil end
        I.Tween(meta.Card, "Fast", { BackgroundTransparency = 1 })
        I.Tween(meta.Stroke, "Fast", { Transparency = 1 })
        I.Tween(meta.Title, "Fast", { TextTransparency = 1 })
        I.Tween(meta.Body, "Fast", { TextTransparency = 1 })
        I.Tween(meta.Progress, "Fast", { BackgroundTransparency = 1 })
        for _, b in ipairs(meta.Actions:GetChildren()) do
            if b:IsA("TextButton") then b:Destroy() end
        end
        if meta.CardScale then I.Tween(meta.CardScale, "Vanish", { Scale = 0.88 }) end
        I.Tween(meta.Card, "Snappy", { Size = UDim2.new(1, 0, 0, 0) }, function()
            if not meta.InUse then meta.Card.Visible = false end
            process()
        end)
        process()
    end

    process = function()
        while active < MAX_ACTIVE and #queue > 0 do
            local item = table.remove(queue, 1)
            local meta = getFreeCard()
            if not meta then
                table.insert(queue, 1, item)
                break
            end
            active += 1
            meta.InUse = true
            local themeKey = TypeColors[item.Type] or "Accent"
            meta.ThemeKey = themeKey
            meta.Card.Visible = true
            meta.Dot.BackgroundColor3 = I.CurrentTheme[themeKey]
            meta.Progress.BackgroundColor3 = I.CurrentTheme[themeKey]
            meta.Title.Text = item.Title
            meta.Body.Text = item.Text

            local textH = 0
            if item.Text ~= "" then
                local b = I.TextService:GetTextSize(item.Text, I.TS(12), Enum.Font.Gotham, Vector2.new(296, 400))
                textH = math.min(b.Y, 120)
                meta.Body.Size = UDim2.new(1, -24, 0, textH)
                meta.Body.Visible = true
            else
                meta.Body.Visible = false
            end

            local actCount = 0
            for _, b in ipairs(meta.Actions:GetChildren()) do
                if b:IsA("TextButton") then b:Destroy() end
            end
            if type(item.Actions) == "table" then
                local cardMaid = I.Maid.new()
                meta.Maid = cardMaid
                for i = 1, math.min(#item.Actions, 3) do
                    local a = item.Actions[i]
                    local b = I.Create("TextButton", {
                        Size = UDim2.fromOffset(64, 24),
                        BackgroundColor3 = I.CurrentTheme.Element,
                        BorderSizePixel = 0,
                        Text = tostring(a.Text or "OK"),
                        Font = Enum.Font.GothamBold,
                        TextSize = 11,
                        TextColor3 = I.CurrentTheme.Text,
                        AutoButtonColor = false,
                        LayoutOrder = i,
                        ZIndex = 3,
                        Parent = meta.Actions,
                        Children = { I.Corner(6) },
                    })
                    I.Bind(b, "BackgroundColor3", "Element")
                    I.Bind(b, "TextColor3", "Text")
                    I.AddHover(b)
                    actCount += 1
                    cardMaid:Give(b.MouseButton1Click:Connect(function()
                        if not meta.InUse then return end
                        dismiss(meta)
                        if type(a.Callback) == "function" then
                            I.SafeCall(a.Callback)
                        end
                    end))
                end
            end

            local cardH = 38 + textH + (actCount > 0 and 30 or 0)
            meta.Card.BackgroundTransparency = 1
            meta.Stroke.Transparency = 1
            meta.Title.TextTransparency = 1
            meta.Body.TextTransparency = 1
            meta.Progress.BackgroundTransparency = 1
            meta.Progress.Size = UDim2.new(1, -24, 0, 2)
            meta.Card.Size = UDim2.new(1, 0, 0, 0)
            if meta.CardScale then meta.CardScale.Scale = 0.9 end
            if meta.DotScale then meta.DotScale.Scale = 0 end
            if not meta.Maid then meta.Maid = I.Maid.new() end

            I.Tween(meta.Card, "Snappy", { Size = UDim2.new(1, 0, 0, cardH) })
            I.Tween(meta.Card, "Snappy", { BackgroundTransparency = 0.04 })
            I.Tween(meta.Stroke, "Snappy", { Transparency = 0.5 })
            I.Tween(meta.Title, "Snappy", { TextTransparency = 0 })
            if textH > 0 then I.Tween(meta.Body, "Snappy", { TextTransparency = 0 }) end
            I.Tween(meta.Progress, "Snappy", { BackgroundTransparency = 0 })
            if meta.CardScale then I.Tween(meta.CardScale, "PopSoft", { Scale = 1 }) end
            if meta.DotScale then I.Tween(meta.DotScale, "Pop", { Scale = 1 }) end

            local duration = math.max(0.5, tonumber(item.Duration) or 4)
            local remaining = duration
            local startedAt = os.clock()
            meta.DelayThread = task.delay(duration, function()
                meta.DelayThread = nil
                dismiss(meta)
            end)
            meta.ProgressTween = I.Tween(meta.Progress,
                TweenInfo.new(duration, Enum.EasingStyle.Linear),
                { Size = UDim2.new(0, 0, 0, 2) })

            meta.Maid:Give(meta.Hit.MouseEnter:Connect(function()
                if not meta.InUse then return end
                if meta.ProgressTween then pcall(function() meta.ProgressTween:Pause() end) end
                if meta.DelayThread then
                    pcall(task.cancel, meta.DelayThread)
                    remaining = math.max(0.05, remaining - (os.clock() - startedAt))
                    meta.DelayThread = nil
                end
            end))
            meta.Maid:Give(meta.Hit.MouseLeave:Connect(function()
                if not meta.InUse then return end
                startedAt = os.clock()
                if meta.ProgressTween then
                    pcall(function() meta.ProgressTween:Cancel() end)
                    meta.ProgressTween = I.Tween(meta.Progress,
                        TweenInfo.new(math.max(0.05, remaining), Enum.EasingStyle.Linear),
                        { Size = UDim2.new(0, 0, 0, 2) })
                end
                meta.DelayThread = task.delay(remaining, function()
                    meta.DelayThread = nil
                    dismiss(meta)
                end)
            end))
            meta.Maid:Give(meta.Hit.MouseButton1Click:Connect(function() dismiss(meta) end))
        end
    end

    function Kailex:Notify(data)
        if type(data) == "string" then data = { Text = data } end
        data = data or {}
        local t = string.lower(tostring(data.Type or "info"))
        if not TypeColors[t] then t = "info" end
        local actions
        if type(data.Actions) == "table" then
            actions = {}
            for i, a in ipairs(data.Actions) do
                if type(a) == "table" and a.Text then
                    actions[#actions + 1] = { Text = a.Text, Callback = a.Callback }
                end
            end
        end
        local entry = {
            Title = data.Title or (t == "info" and "Notice" or (t:sub(1,1):upper() .. t:sub(2))),
            Text = tostring(data.Text or data.Description or ""),
            Duration = data.Duration,
            Type = t,
            Actions = actions,
        }
        table.insert(NotificationLog, { Title = entry.Title, Text = entry.Text, Type = t, Time = os.time() })
        while #NotificationLog > 50 do table.remove(NotificationLog, 1) end
        table.insert(queue, entry)
        process()
    end
end


-- [[Core/Misc/Callbacks]]
Bundle["Core/Misc/Callbacks"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local Setting = I.Setting

    local function RunCallback(fn, ctxName, ...)
        if type(fn) ~= "function" then return end
        if Setting.AsyncCallbacks then
            local args = table.pack(...)
            task.spawn(function()
                local ok, err = pcall(fn, table.unpack(args, 1, args.n))
                if not ok then
                    warn("[Kailex] " .. tostring(err))
                    Kailex:Notify({
                        Title = "Callback error" .. (ctxName and (" - " .. ctxName) or ""),
                        Text = tostring(err), Type = "Error", Duration = 6,
                    })
                end
            end)
        else
            I.SafeCall(fn, ...)
        end
    end

    local function CopyToClipboard(text)
        local setc
        local ok, sc = pcall(function() return setclipboard or toclipboard or setrbxclipboard end)
        if ok then setc = sc end
        if type(setc) == "function" then
            pcall(setc, tostring(text))
            Kailex:Notify({ Title = "Copied", Text = tostring(text), Type = "Success", Duration = 2 })
        else
            Kailex:Notify({ Title = "Copy", Text = tostring(text), Duration = 6 })
        end
    end

    I.RunCallback = RunCallback
    I.CopyToClipboard = CopyToClipboard
end


-- [[Core/Overlays/Confirm]]
Bundle["Core/Overlays/Confirm"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex
    local Setting = I.Setting
    local TextService = I.TextService

    local ModalActive = false

    function Kailex:Confirm(data, onAccept)
        if ModalActive then return nil end
        if type(data) == "string" then data = { Text = data } end
        data = data or {}
        if type(onAccept) == "function" then data.OnAccept = onAccept end
        for _, w in ipairs(Kailex.Windows) do
            if not w._destroyed and w._closeDropdowns then w:_closeDropdowns() end
        end
        ModalActive = true
        local maid = I.Maid.new()
        maid:Give(function() ModalActive = false end)

        local dimmer = I.Create("TextButton", {
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.new(0, 0, 0),
            BackgroundTransparency = 1,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 300,
            Parent = I.LayerOverlay,
        })
        maid:Give(dimmer)
        maid:Link(dimmer)

        local card = I.Create("CanvasGroup", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(360, 200),
            BackgroundColor3 = I.CurrentTheme.Surface,
            BorderSizePixel = 0,
            GroupTransparency = 1,
            ZIndex = 301,
            Parent = I.LayerOverlay,
            Children = { I.Corner(12), I.StrokeBind(1, "Stroke", 0.4) },
        })
        I.Bind(card, "BackgroundColor3", "Surface")
        maid:Give(card)
        I.Create("UIPadding", {
            PaddingLeft = UDim.new(0, 18), PaddingRight = UDim.new(0, 18),
            PaddingTop = UDim.new(0, 16), PaddingBottom = UDim.new(0, 16),
            Parent = card,
        })

        local title = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 18),
            Font = Enum.Font.GothamBold,
            TextSize = 15,
            TextColor3 = I.CurrentTheme.Text,
            TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Text = data.Title or "Are you sure?",
            Parent = card,
        })
        I.Bind(title, "TextColor3", "Text")

        local bodyText = tostring(data.Text or data.Description or "")
        local b = TextService:GetTextSize(bodyText, I.TS(13), Enum.Font.Gotham, Vector2.new(324, 300))
        local bodyH = math.min(b.Y, 140)
        local body = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(0, 24),
            Size = UDim2.new(1, 0, 0, bodyH),
            Font = Enum.Font.Gotham,
            TextSize = 13,
            TextColor3 = I.CurrentTheme.SubText,
            TextWrapped = true,
            TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            Text = bodyText,
            Parent = card,
        })
        I.Bind(body, "TextColor3", "SubText")

        local btnRow = I.Create("Frame", {
            BackgroundTransparency = 1,
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new(0, 0, 1, 0),
            Size = UDim2.new(1, 0, 0, 34),
            Parent = card,
        })

        local function mkBtn(text, accent, pos)
            local btn = I.Create("TextButton", {
                Position = pos,
                Size = UDim2.new(0.48, -4, 1, 0),
                BackgroundColor3 = accent and I.CurrentTheme.Accent or I.CurrentTheme.Element,
                Text = text,
                Font = Enum.Font.GothamBold,
                TextSize = 13,
                TextColor3 = accent and I.CurrentTheme.OnAccent or I.CurrentTheme.Text,
                AutoButtonColor = false,
                BorderSizePixel = 0,
                Parent = btnRow,
                Children = { I.Corner(8) },
            })
            if accent then
                I.Bind(btn, "BackgroundColor3", "Accent")
                I.Bind(btn, "TextColor3", "OnAccent")
                I.AddHover(btn, { HoverKey = "AccentHover", BaseKey = "Accent" })
            else
                I.Bind(btn, "BackgroundColor3", "Element")
                I.Bind(btn, "TextColor3", "Text")
                I.AddHover(btn)
            end
            return btn
        end

        local decline = mkBtn(data.DeclineText or data.CancelText or "Cancel", false, UDim2.new(0, 0, 0, 0))
        local accept  = mkBtn(data.AcceptText  or data.ConfirmText or "Confirm", true,  UDim2.new(0.52, 0, 0, 0))

        card.Size = UDim2.fromOffset(360, 16 + 18 + 6 + bodyH + 14 + 34 + 16)

        local scale = I.Create("UIScale", { Scale = 0.88, Parent = card })

        local closed = false
        local modalEntry
        local function close(accepted)
            if closed then return end
            closed = true
            I.ModalManager.Remove(modalEntry)
            I.Tween(dimmer, "Fast", { BackgroundTransparency = 1 })
            I.Tween(scale, "Vanish", { Scale = 0.92 })
            I.Tween(card, "Fast", { GroupTransparency = 1 })
            if accepted and data.OnAccept then I.SafeCall(data.OnAccept, true) end
            if not accepted and data.OnDecline then I.SafeCall(data.OnDecline, false) end
            task.delay(0.2, function()
                maid:Destroy()
            end)
        end

        modalEntry = I.ModalManager.Push(nil, function() close(false) end)

        maid:Give(accept.MouseButton1Click:Connect(function()
            close(true)
            I.ApplyRipple(accept)
            I.PlaySound("Click")
        end))
        maid:Give(decline.MouseButton1Click:Connect(function()
            close(false)
            I.ApplyRipple(decline)
            I.PlaySound("Click")
        end))
        maid:Give(dimmer.MouseButton1Click:Connect(function() close(false) end))

        local hook = I.AddInputHook(function() return not closed end, function(input, gp)
            if gp then return end
            if input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then
                close(true)
            elseif input.KeyCode == Enum.KeyCode.Escape then
                close(false)
            end
        end)
        maid:Give(function() I.RemoveInputHook(hook) end)

        I.Tween(dimmer, "Normal", { BackgroundTransparency = 0.5 })
        I.Tween(card, "Snappy", { GroupTransparency = 0 })
        I.Tween(scale, "Pop", { Scale = 1 })
        return card
    end
end


-- [[Core/Misc/QuickWidgets]]
Bundle["Core/Misc/QuickWidgets"] = function(ctx)
    local I = ctx.Internal
    local Kailex = ctx.Kailex

    local QuickWidgets = { Active = {} }
    I.QuickWidgets = QuickWidgets

    function QuickWidgets.Destroy(el)
        local w = QuickWidgets.Active[el]
        if not w then return end
        QuickWidgets.Active[el] = nil
        I.Tween(w.Frame, "Collapse", { Size = UDim2.fromOffset(0, 0) }, function()
            w.Maid:Destroy()
            w.Frame:Destroy()
        end)
    end

    function QuickWidgets.Toggle(element)
        if QuickWidgets.Active[element] then
            QuickWidgets.Destroy(element)
            return
        end
        local count = 0
        for _ in pairs(QuickWidgets.Active) do count += 1 end
        local name = element.Title
        local s = I.GetScale()
        local widget = I.Create("Frame", {
            Size = UDim2.fromOffset(0, 0),
            Position = UDim2.fromOffset((I.Viewport.X - 70) / s, (I.Viewport.Y * 0.35 + count * 56) / s),
            BackgroundColor3 = I.CurrentTheme.Surface,
            BorderSizePixel = 0,
            ZIndex = 20,
            Parent = I.LayerWindows,
            Children = { I.Corner(12), I.StrokeBind(1, "Stroke", 0.4) },
        })
        I.Bind(widget, "BackgroundColor3", "Surface")
        local wMaid = I.Maid.new()
        wMaid:Link(widget)
        QuickWidgets.Active[element] = { Frame = widget, Maid = wMaid }

        local state = element:Get() == true
        local hit = I.Create("TextButton", {
            BackgroundTransparency = 1, Text = "",
            Size = UDim2.fromScale(1, 1),
            Parent = widget,
        })
        local letter = I.Create("TextLabel", {
            BackgroundTransparency = 1,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.42),
            Size = UDim2.fromOffset(20, 20),
            Font = Enum.Font.GothamBold,
            TextSize = 14,
            TextColor3 = I.CurrentTheme.Text,
            Text = name:sub(1, 1):upper(),
            Parent = widget,
        })
        I.Bind(letter, "TextColor3", "Text")
        local dot = I.Create("Frame", {
            AnchorPoint = Vector2.new(0.5, 1),
            Position = UDim2.new(0.5, 0, 1, -8),
            Size = UDim2.fromOffset(6, 6),
            BackgroundColor3 = state and I.CurrentTheme.Accent or I.CurrentTheme.Stroke,
            BorderSizePixel = 0,
            Parent = widget,
            Children = { I.Create("UICorner", { CornerRadius = UDim.new(1, 0) }) },
        })
        local closeB = I.Create("TextButton", {
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, -2, 0, 2),
            Size = UDim2.fromOffset(14, 14),
            BackgroundTransparency = 1,
            Text = "x",
            Font = Enum.Font.GothamBold,
            TextSize = 12,
            TextColor3 = I.CurrentTheme.SubText,
            Parent = widget,
        })
        I.Bind(closeB, "TextColor3", "SubText")

        local function refresh()
            dot.BackgroundColor3 = state and I.CurrentTheme.Accent or I.CurrentTheme.Stroke
        end
        refresh()
        I.MakeDraggable(hit, widget, { Clamp = true })
        wMaid:Give(hit.MouseButton1Click:Connect(function()
            if hit:GetAttribute("Dragging") then return end
            I.ApplyRipple(hit)
            state = not state
            element:Set(state)
            refresh()
        end))
        wMaid:Give(closeB.MouseButton1Click:Connect(function() QuickWidgets.Destroy(element) end))
        wMaid:Give(element.Changed:Connect(function(v)
            state = v == true
            refresh()
        end))

        local letterScale = I.Create("UIScale", { Parent = letter })
        letterScale.Scale = 0.2
        I.Tween(letterScale, "Pop", { Scale = 1 })
        I.Tween(widget, "SpringBig", { Size = UDim2.fromOffset(46, 46) })
    end

    table.insert(I.ViewportHooks, function()
        for _, w in pairs(QuickWidgets.Active) do I.ClampFloat(w.Frame) end
        if Kailex._mobileButton then I.ClampFloat(Kailex._mobileButton) end
    end)
end


-- [[Core/Overlays/ContextMenu]]
Bundle["Core/Overlays/ContextMenu"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting

    local ContextMenu = {}
    I.ContextMenu = ContextMenu

    local frame, catcher
    local entry = nil
    local hideToken = 0

    local function build()
        frame = I.Create("Frame", {
            BackgroundColor3 = I.CurrentTheme.SurfaceLight,
            BorderSizePixel = 0,
            Visible = false,
            ZIndex = 320,
            Parent = I.LayerOverlay,
            Children = {
                I.Corner(10), I.StrokeBind(1, "Stroke", 0.25),
                I.Create("UIListLayout", { Padding = UDim.new(0, 2), SortOrder = Enum.SortOrder.LayoutOrder }),
                I.Create("UIPadding", {
                    PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6),
                    PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6),
                }),
            },
        })
        I.Bind(frame, "BackgroundColor3", "SurfaceLight")
        catcher = I.Create("TextButton", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Text = "",
            Visible = false,
            ZIndex = 310,
            Parent = I.LayerOverlay,
        })
        catcher.MouseButton1Click:Connect(function() ContextMenu.Hide() end)
    end

    function ContextMenu.Show(items, x, y)
        if not items or #items == 0 then return end
        if not frame then build() end
        hideToken += 1
        for _, ch in ipairs(frame:GetChildren()) do
            if ch:IsA("TextButton") or (ch:IsA("Frame") and ch.Name == "__sep") then ch:Destroy() end
        end
        local width = 140
        local totalH = 12
        for i, item in ipairs(items) do
            if item.Separator then
                local sep = I.Create("Frame", {
                    Name = "__sep",
                    BackgroundColor3 = I.CurrentTheme.Stroke,
                    BackgroundTransparency = 0.4,
                    BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, 1),
                    LayoutOrder = i,
                    Parent = frame,
                })
                I.Bind(sep, "BackgroundColor3", "Stroke")
                totalH += 3
            else
                local text = tostring(item.Text or "")
                local b = I.TextService:GetTextSize(text, I.TS(12), Enum.Font.Gotham, Vector2.new(400, 20))
                if b.X + 26 > width then width = b.X + 26 end
                local btn = I.Create("TextButton", {
                    Size = UDim2.new(1, 0, 0, 26),
                    BackgroundColor3 = I.CurrentTheme.Element,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Text = text,
                    Font = Enum.Font.Gotham,
                    TextSize = 12,
                    TextColor3 = item.Danger and I.CurrentTheme.Error or I.CurrentTheme.Text,
                    TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
                    AutoButtonColor = false,
                    LayoutOrder = i,
                    Parent = frame,
                    Children = { I.Create("UICorner", { CornerRadius = UDim.new(0, 6) }) },
                })
                I.Bind(btn, "BackgroundColor3", "Element")
                if item.Danger then
                    I.Bind(btn, "TextColor3", "Error")
                else
                    I.Bind(btn, "TextColor3", "Text")
                end
                I.AddHover(btn)
                btn.MouseButton1Click:Connect(function()
                    ContextMenu.Hide()
                    if type(item.Callback) == "function" then
                        task.defer(function() I.SafeCall(item.Callback) end)
                    end
                end)
                totalH += 28
            end
        end
        frame.Size = UDim2.fromOffset(width, totalH)
        local s = I.GetScale()
        local fw, fh = width * s, totalH * s
        local px = math.clamp(x, 8, math.max(8, I.Viewport.X - fw - 8))
        local py = math.clamp(y, 8, math.max(8, I.Viewport.Y - fh - 8))
        frame.Position = UDim2.fromOffset(px / s, py / s)
        frame.Visible = true
        catcher.Visible = true
        I.ModalManager.Remove(entry)
        local tk = hideToken
        entry = I.ModalManager.Push(nil, function()
            if hideToken == tk then ContextMenu.Hide() end
        end)
    end

    function ContextMenu.Hide()
        if frame and frame.Visible then
            hideToken += 1
            frame.Visible = false
            catcher.Visible = false
        end
        I.ModalManager.Remove(entry)
        entry = nil
    end

    I.LibMaid:Give(function() ContextMenu.Hide() end)
end


-- [[Elements/Base]]
Bundle["Elements/Base"] = function(ctx)
    local I = ctx.Internal
    local Setting = I.Setting

    local Elements = {}
    I.Elements = Elements

    local Element = {}
    Element.__index = Element
    I.Element = Element

    function Element:_init(row, opts, tab)
        opts = opts or {}
        self._opts = opts
        self.Row = row
        self.Maid = I.Maid.new()
        self.Maid:Link(row)
        self.Tab = tab
        self.Title = tostring(opts.Name or opts.Title or "Element")
        self._searchExtra = tostring(opts.Search or opts.Tooltip or opts.Description or "")
        self.SearchText = (self.Title .. " " .. self._searchExtra):lower()
        self._destroyed = false
        self._extras = {}
        self._manualVisible = true
        self._disabled = false
        self._tooltip = { Text = opts.Tooltip }
        if opts.Tooltip then I.AddTooltip(row, self._tooltip) end
        if tab then
            table.insert(tab.Elements, self)
            if tab.CurrentSection then
                table.insert(tab.CurrentSection.Elements, self)
                self.Section = tab.CurrentSection
                if tab.CurrentSection.Collapsed then
                    row.Visible = false
                end
            end
        end
        return self
    end

    function Element:_bindSaveReload(saveKey, fn)
        if not saveKey then return end
        local reg = I.SaveReloadRegistry
        if not reg then return end
        local list = reg[saveKey]
        if not list then list = {} reg[saveKey] = list end
        table.insert(list, fn)
        self.Maid:Give(function()
            for i, f in ipairs(list) do
                if f == fn then table.remove(list, i) break end
            end
        end)
    end

    function Element:SetTitle(text)
        if self._destroyed then return end
        self.Title = tostring(text or "")
        self.SearchText = (self.Title .. " " .. self._searchExtra):lower()
        if self.TitleLabel and self.TitleLabel.Parent then self.TitleLabel.Text = self.Title end
    end

    function Element:SetTooltip(text)
        if self._destroyed then return end
        self._tooltip.Text = tostring(text or "")
    end

    function Element:Visible(state)
        if self._destroyed then return end
        if state == nil then
            self.Row.Visible = not self.Row.Visible
        else
            self.Row.Visible = state and true or false
        end
        self._manualVisible = self.Row.Visible
        if self.Section and self.Section.Collapsed then
            self.Row.Visible = false
        end
    end

    function Element:SetDisabled(state)
        if self._destroyed then return end
        local v = state == true
        if v == self._disabled then return end
        self._disabled = v
        if self.Row then self.Row:SetAttribute("Disabled", v) end
        if self.TitleLabel then I.Tween(self.TitleLabel, "Fast", { TextTransparency = v and 0.55 or 0 }) end
        local st = self.Row and self.Row:FindFirstChildOfClass("UIStroke")
        if st then I.Tween(st, "Fast", { Transparency = v and 0.9 or 0.65 }) end
    end

    function Element:IsDisabled()
        return self._disabled == true
    end

    function Element:RecalcWidth()
        if not self.RightContainer then return end
        local w = (self._baseRightW or 0) + (self._extraW or 0)
        self.RightContainer.Size = UDim2.new(0, w, 1, -4)
        if self.LeftFrame then
            self.LeftFrame.Size = UDim2.new(1, -w, 1, 0)
        end
    end

    function Element:AddExtra(className, opts)
        if self._destroyed then return nil end
        local elClass = Elements[className]
        if not elClass then return nil end
        opts = opts or {}
        local el = elClass.new(self.Tab, opts)

        local row = el.Row
        local pad = row:FindFirstChildOfClass("UIPadding")
        if pad then pad:Destroy() end
        row.BackgroundTransparency = 1
        row:SetAttribute("NoHoverFX", true)
        local rowStroke = row:FindFirstChildOfClass("UIStroke")
        if rowStroke then rowStroke.Transparency = 1 end
        if el.LeftFrame then
            el.LeftFrame.Size = UDim2.new(0, 0, 1, 0)
        end
        if el.TitleLabel and el.TitleLabel:IsA("TextLabel") then
            el.TitleLabel.Visible = false
        end
        if el.RightContainer then
            el.RightContainer.AnchorPoint = Vector2.new(0, 0.5)
            el.RightContainer.Position = UDim2.new(0, 0, 0.5, 0)
            el.RightContainer.Size = UDim2.new(1, 0, 1, 0)
        end

        row.Parent = self.RightContainer
        row.LayoutOrder = (#self._extras + 1) + 10
        row.Size = UDim2.new(0, el._width or 0, 0, el._extraH or I.ROW_H)

        for i, v in ipairs(self.Tab.Elements) do
            if v == el then table.remove(self.Tab.Elements, i) break end
        end
        if el.Section then
            for i, v in ipairs(el.Section.Elements) do
                if v == el then table.remove(el.Section.Elements, i) break end
            end
            el.Section = nil
        end

        table.insert(self._extras, el)
        self._extraW = (self._extraW or 0) + (el._width or 0)
        self:RecalcWidth()

        el.Maid:Give(function()
            if self._destroyed then return end
            for i, v in ipairs(self._extras) do
                if v == el then table.remove(self._extras, i) break end
            end
            self._extraW = math.max(0, (self._extraW or 0) - (el._width or 0))
            self:RecalcWidth()
        end)

        return el
    end

    function Element:AddToggle(opts)
        if self._destroyed then return nil end
        if self.AttachedToggle then return self.AttachedToggle end
        opts = opts or {}
        local tg = self:AddExtra("Toggle", opts)
        if not tg then return nil end
        self.AttachedToggle = tg
        self.Enabled = tg.Changed
        function self:IsEnabled() return tg:Get() == true end
        function self:SetEnabled(v, silent) tg:Set(v == true, silent) end
        return tg
    end

    function Element:_contextItems()
        local items = {}
        if self.CopyValue then
            table.insert(items, { Text = "Copy value", Callback = function()
                local v = self:CopyValue()
                if v ~= nil then I.CopyToClipboard(v) end
            end })
        end
        if self.Reset then
            table.insert(items, { Text = "Reset to default", Callback = function() self:Reset() end })
        end
        table.insert(items, {
            Text = self._disabled and "Enable" or "Disable",
            Callback = function() self:SetDisabled(not self._disabled) end,
        })
        return items
    end

    local function HookContextMenu(el, overlay)
        overlay.MouseButton2Click:Connect(function()
            if el._destroyed then return end
            local items = el:_contextItems()
            if #items == 0 then return end
            local m = I.UserInputService:GetMouseLocation()
            I.ContextMenu.Show(items, m.X, m.Y)
        end)
    end
    I.HookContextMenu = HookContextMenu

    function Element:Destroy()
        if self._destroyed then return end
        self._destroyed = true
        if I.HotElement == self then I.HotElement = nil end
        local tab = self.Tab
        if tab then
            for i, el in ipairs(tab.Elements) do
                if el == self then table.remove(tab.Elements, i) break end
            end
            if self.IsSection then
                for i, s in ipairs(tab.Sections) do
                    if s == self then table.remove(tab.Sections, i) break end
                end
                if tab.CurrentSection == self then tab.CurrentSection = nil end
                for _, el in ipairs(self.Elements) do
                    if not el._destroyed then el.Section = nil end
                end
            end
            if self.Section then
                for i, el in ipairs(self.Section.Elements) do
                    if el == self then table.remove(self.Section.Elements, i) break end
                end
            end
        end
        for _, ex in ipairs(self._extras) do
            if not ex._destroyed then ex:Destroy() end
        end
        if self.Changed then self.Changed:Destroy() end
        if self.Maid then self.Maid:Destroy() end
        if self.Row then self.Row:Destroy() end
        self.Row, self.Maid, self.Tab, self.Section = nil, nil, nil, nil
    end

    local function CreateRow(parent, opts)
        opts = opts or {}
        local desc = opts.Description and tostring(opts.Description) or nil
        local height = opts.Height or (desc and (I.ROW_H + 16) or I.ROW_H)
        local rowProps = {
            Size = UDim2.new((opts.Width or 1), -3, 0, height),
            BackgroundColor3 = I.CurrentTheme.Element,
            BackgroundTransparency = 0.25,
            BorderSizePixel = 0,
            Parent = parent,
            Children = { I.Corner(8), I.StrokeBind(1, "Stroke", 0.65) },
        }
        if type(opts.Order) == "number" then
            rowProps.LayoutOrder = opts.Order
        end
        local row = I.Create("Frame", rowProps)
        I.Bind(row, "BackgroundColor3", "Element")
        I.Create("UIPadding", {
            PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12),
            PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 2),
            Parent = row,
        })

        local rightW = opts.RightWidth or 0
        local leftFrame = I.Create("Frame", {
            BackgroundTransparency = 1,
            Size = UDim2.new(1, -rightW, 1, 0),
            Parent = row,
        })
        local title, descLabel
        if desc then
            title = I.Create("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, -4, 0, 15),
                Position = UDim2.new(0, 0, 0, 2),
                Font = Enum.Font.GothamMedium,
                TextSize = 13,
                TextColor3 = I.CurrentTheme.Text,
                TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Text = opts.Name or "",
                Parent = leftFrame,
            })
            descLabel = I.Create("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, -4, 0, 13),
                Position = UDim2.new(0, 0, 0, 17),
                Font = Enum.Font.Gotham,
                TextSize = 11,
                TextColor3 = I.CurrentTheme.SubText,
                TextTransparency = 0.35,
                TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Text = desc,
                Parent = leftFrame,
            })
            I.Bind(descLabel, "TextColor3", "SubText")
        else
            title = I.Create("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, -4, 1, 0),
                Position = UDim2.fromOffset(0, 0),
                Font = Enum.Font.GothamMedium,
                TextSize = 13,
                TextColor3 = I.CurrentTheme.Text,
                TextXAlignment = Setting.RTL and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Text = opts.Name or "",
                Parent = leftFrame,
            })
        end
        I.Bind(title, "TextColor3", "Text")

        local right = I.Create("Frame", {
            BackgroundTransparency = 1,
            AnchorPoint = Vector2.new(Setting.RTL and 0 or 1, 0.5),
            Position = Setting.RTL and UDim2.new(0, 0, 0.5, 0) or UDim2.new(1, 0, 0.5, 0),
            Size = UDim2.new(0, rightW, 1, -4),
            Parent = row,
            Children = {
                I.Create("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalAlignment = Setting.RTL and Enum.HorizontalAlignment.Left or Enum.HorizontalAlignment.Right,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    Padding = UDim.new(0, 8),
                    SortOrder = Enum.SortOrder.LayoutOrder,
                }),
            },
        })

        if not opts.NoHover then
            I.AddHover(row, { StrokeTransparency = 0.65 })
        end
        return row, title, right, leftFrame, descLabel
    end
    I.CreateRow = CreateRow

    local function MakeElementClass()
        local class = {}
        class.__index = class
        setmetatable(class, { __index = Element })
        return class
    end
    I.MakeElementClass = MakeElementClass
end


